fn delete_and_change_visibility() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.create("other", json!({}));
    s.send("q", "a");
    let h = s.receive("q")[0]["ReceiptHandle"].as_str().unwrap().to_owned();
    let delete = |s: &mut Session, q: &str, h: &str| s.call(json!({"Command": "DeleteMessage", "QueueName": q, "ReceiptHandle": h}));
    for bad in ["r-01", "R-1", "r-1 ", "r-2", "r-0", "x", "", "r-+1", "r-99999999999999999999999"] {
        assert_eq!(delete(&mut s, "q", bad)["error"]["code"], "ReceiptHandleInvalid", "{bad}");
    }
    assert_eq!(delete(&mut s, "other", &h)["error"]["code"], "ReceiptHandleExpired");
    s.ok(json!({"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": h, "VisibilityTimeout": 100}));
    s.tick(99);
    assert_eq!(s.receive("q").len(), 0);
    s.ok(json!({"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": h, "VisibilityTimeout": 0}));
    assert_eq!(s.counts("q")["Visible"], 1);
    // The handle is not usable once the message is visible again.
    assert_eq!(delete(&mut s, "q", &h)["error"]["code"], "ReceiptHandleExpired");
