    pub fn record_send(
        &mut self,
        dedup_id: String,
        now: u64,
        message_id: u64,
        sequence_number: Option<u64>,
    ) {
        self.dedup.insert(
            dedup_id,
            DedupEntry {
                accepted_at: now,
                message_id,
                sequence_number,
            },
        );
    }

    /// Delivers up to `max` messages (SPEC section 6, *ReceiveMessage*).
    /// `next_handle` is the process-wide receipt handle counter. The queue
    /// must have been advanced to `now`.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        visibility_timeout: u64,
        next_handle: &mut u64,
    ) -> Received {
        let dead_letter_limit = self
            .attributes
            .dead_letter
            .as_ref()
